### prompt
Write a program in Free Pascal's objfpc mode that declares a generic function to count how many times a given value appears in a dynamic array. The program must test the function with an array of integers and an array of strings, printing the counts for specific values.
### answer
The program defines a generic function `CountOccurrences<T>` that takes a dynamic array and a value of type `T`, then iterates through the array to count matches. It tests the function with an integer array (counting `3`) and a string array (counting `'apple'`), printing the results.

```pascal
program GenericCount;

{$mode objfpc}{$H+}

uses
  SysUtils;

generic function CountOccurrences<T>(const Arr: array of T; const Value: T): Integer;
var
  I: Integer;
begin
  Result := 0;
  for I := Low(Arr) to High(Arr) do
    if Arr[I] = Value then
      Inc(Result);
end;

var
  Integers: array of Integer;
  Strings: array of String;
  Count: Integer;
begin
  SetLength(Integers, 5);
  Integers[0] := 1;
  Integers[1] := 3;
  Integers[2] := 2;
  Integers[3] := 3;
  Integers[4] := 3;

  Count := specialize CountOccurrences<Integer>(Integers, 3);
  WriteLn('Count of 3 in integers: ', Count);

  SetLength(Strings, 4);
  Strings[0] := 'banana';
  Strings[1] := 'apple';
  Strings[2] := 'orange';
  Strings[3] := 'apple';

  Count := specialize CountOccurrences<String>(Strings, 'apple');
  WriteLn('Count of "apple" in strings: ', Count);
end.
```

