Extend the following Free Pascal program in objfpc mode to add a method that calculates the product of all even numbers in an array of integers. The method should be virtual and belong to a base class `TNumberProcessor`, which is then inherited by `TArrayProcessor`. The program should print the product of even numbers in the array `[3, 4, 5, 6, 7, 8]`.

```pascal
program ExtendNumberProcessor;

{$mode objfpc}{$H+}

uses
  SysUtils;

type
  TNumberProcessor = class
    function ProcessNumbers(const Numbers: array of Integer): Integer; virtual; abstract;
  end;

  TArrayProcessor = class(TNumberProcessor)
    function ProcessNumbers(const Numbers: array of Integer): Integer; override;
  end;

{ TArrayProcessor }

function TArrayProcessor.ProcessNumbers(const Numbers: array of Integer): Integer;
var
  I, Sum: Integer;
begin
  Sum := 0;
  for I := Low(Numbers) to High(Numbers) do
    Sum := Sum + Numbers[I];
  Result := Sum;
end;

var
  Processor: TNumberProcessor;
  Numbers: array of Integer = (3, 4, 5, 6, 7, 8);
begin
  Processor := TArrayProcessor.Create;
  try
    WriteLn('Sum of numbers: ', Processor.ProcessNumbers(Numbers));
  finally
    Processor.Free;
  end;
end.
```
### answer
The program is extended by adding a virtual method `ProductOfEvens` to the base class `TNumberProcessor`, which is then overridden in `TArrayProcessor` to calculate the product of even numbers. A method pointer is used to dynamically call this new method.

```pascal
program ExtendNumberProcessor;

{$mode objfpc}{$H+}

uses
  SysUtils;

type
  TNumberProcessor = class
    function ProcessNumbers(const Numbers: array of Integer): Integer; virtual; abstract;
    function ProductOfEvens(const Numbers: array of Integer): Integer; virtual; abstract;
  end;

  TArrayProcessor = class(TNumberProcessor)
    function ProcessNumbers(const Numbers: array of Integer): Integer; override;
    function ProductOfEvens(const Numbers: array of Integer): Integer; override;
  end;

{ TArrayProcessor }

function TArrayProcessor.ProcessNumbers(const Numbers: array of Integer): Integer;
var
  I, Sum: Integer;
begin
  Sum := 0;
  for I := Low(Numbers) to High(Numbers) do
    Sum := Sum + Numbers[I];
  Result := Sum;
end;

function TArrayProcessor.ProductOfEvens(const Numbers: array of Integer): Integer;
var
  I, Product: Integer;
begin
  Product := 1;
  for I := Low(Numbers) to High(Numbers) do
    if Numbers[I] mod 2 = 0 then
      Product := Product * Numbers[I];
  Result := Product;
end;

var
  Processor: TNumberProcessor;
  Numbers: array of Integer = (3, 4, 5, 6, 7, 8);
  ProductMethod: function(const Numbers: array of Integer): Integer of object;
begin
  Processor := TArrayProcessor.Create;
  try
    WriteLn('Sum of numbers: ', Processor.ProcessNumbers(Numbers));

    ProductMethod := @Processor.ProductOfEvens;
    WriteLn('Product of even numbers: ', ProductMethod(Numbers));
  finally
    Processor.Free;
  end;
end.
```

