```pascal
{$mode unleashed}
program BoundingBox;

type
  TPoint = record
    X, Y: Integer;
  end;

const
  Points: array[0..4] of TPoint = (
    (X: 1; Y: 2),
    (X: 3; Y: 5),
    (X: 0; Y: 0),
    (X: 4; Y: 1),
    (X: 2; Y: 3)
  );

var
  MinX, MinY, MaxX, MaxY: Integer;
  I: Integer;
begin
  MinX := Points[0].X;
  MinY := Points[0].Y;
  MaxX := Points[0].X;
  MaxY := Points[0].Y;

