### prompt
Write an Oxygene program that defines a `Point` record with integer `X` and `Y` fields. Implement a function that takes a list of `Point` records and returns the point with the smallest Euclidean distance from the origin (0, 0). If the list is empty, return a default point (0, 0). Use a lambda expression to compute the squared distance (avoid floating-point operations for efficiency).
Print the result in the format `Closest point: (X, Y)`.
### answer
The program defines a simple `Point` record and uses a lambda to calculate the squared distance from the origin. It then iterates through the list of points to find the one with the smallest distance. The code avoids LINQ to simplify the structure and ensure correct syntax.

```pascal
namespace ClosestPoint;

uses
  System,
  System.Collections.Generic;

type
  Point = record
    X: Integer;
    Y: Integer;
  end;

  Program = class
  public
    class method FindClosest(points: List<Point>): Point;
    begin
      if points.Count = 0 then
        exit new Point(X := 0, Y := 0);

      var closest := points[0];
      var minDistance := Integer.MaxValue;
      var distanceSquared := method(p: Point): Integer begin exit p.X * p.X + p.Y * p.Y; end;

      for var i := 0 to points.Count - 1 do
      begin
        var current := points[i];
        var currentDistance := distanceSquared(current);
        if currentDistance < minDistance then
        begin
          minDistance := currentDistance;
          closest := current;
        end;
      end;
      exit closest;
    end;

    class method Main(args: array of String): Int32;
    begin
      var points := new List<Point>;
      points.Add(new Point(X := 3, Y := 4));
      points.Add(new Point(X := 1, Y := 1));
      points.Add(new Point(X := 0, Y := 5));
      points.Add(new Point(X := -2, Y := -2));

      var closest := FindClosest(points);
      writeLn('Closest point: (' + closest.X.ToString() + ', ' + closest.Y.ToString() + ')');
      exit 0;
    end;
  end;

end.
```

